using AcxiomCRM.Data; using AcxiomCRM.Models; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers; [ApiController][Route("api/customers")][Authorize] public class ApiCustomersController:ControllerBase{private readonly ApplicationDbContext _db;public ApiCustomersController(ApplicationDbContext db)=>_db=db;[HttpGet]public async Task<IActionResult>Get()=>Ok(await _db.Customers.ToListAsync());[HttpGet("{id}")]public async Task<IActionResult>Get(int id)=>await _db.Customers.FindAsync(id) is Customer c?Ok(c):NotFound();[HttpPost]public async Task<IActionResult>Post(Customer c){if(!ModelState.IsValid)return ValidationProblem(ModelState);_db.Customers.Add(c);await _db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=c.CustomerId},c);}[HttpDelete("{id}")]public async Task<IActionResult>Delete(int id){var c=await _db.Customers.FindAsync(id);if(c==null)return NotFound();c.Status="Inactive";await _db.SaveChangesAsync();return NoContent();}}
